    # This is a complex part. I need to resolve inheritance.
    all_contracts = {}
    for file_path, src in sources.items():
        for contract_name, contract_data in src['contracts'].items():
            members, structs, enums = get_contract_members(contract_data['body'], contract_name)
            all_contracts[f"{file_path}:{contract_name}"] = {
                'file': file_path,
                'name': contract_name,
                'kind': contract_data['kind'],
                'bases': contract_data['bases'],
                'members': members,
                'structs': structs,
                'enums': enums
            }

    # Simple inheritance resolution (not full C3 but works for many cases)
    # We'll just collect all members from all bases
    final_abis = {}
    for full_name, data in all_contracts.items():
        abi = []
        seen_funcs = set()

        def collect_members(contract_full_name):
            c = all_contracts.get(contract_full_name)
            if not c:
                # Try finding by just contract name if full name not found
                # (This is a bit hacky)
                name_only = contract_full_name.split(':')[-1]
                for k, v in all_contracts.items():
                    if v['name'] == name_only:
                        c = v
                        break
            if not c: return

            # Bases are processed first for ABI order? 
            # Actually, child members usually come after parent members or vice-versa.
            # Let's check the executable's order.
            for base in c['bases']:
                collect_members(base)

