                if m['type'] == 'function':
                    sig = m['name'] + '(' + ','.join([canonicalize_type(i['type']) for i in m['inputs']]) + ')'
                    if sig not in seen_funcs:
                        abi.append(m)
                        seen_funcs.add(sig)
