        # So it's bases first.
        collect_members(full_name)

        # Formatting ABI for JSON
        formatted_abi = []
        for m in abi:
            item = {'type': m['type']}
            if 'name' in m: item['name'] = m['name']
            item['inputs'] = [{'name': i['name'], 'type': canonicalize_type(i['type']), 'internalType': i['type']} for i in m['inputs']]
            if m['type'] == 'function':
                item['outputs'] = [{'name': i['name'], 'type': canonicalize_type(i['type']), 'internalType': i['type']} for i in m['outputs']]
                item['stateMutability'] = m['stateMutability']
            elif m['type'] == 'constructor':
                item['stateMutability'] = m['stateMutability']
            elif m['type'] == 'event':
                item['anonymous'] = m['anonymous']
                for i, inp in enumerate(item['inputs']):
                    inp['indexed'] = m['inputs'][i]['indexed']

            formatted_abi.append(item)
        final_abis[full_name] = formatted_abi

    return final_abis

