#!/usr/bin/env python3
import sys
import os
import re
import json
import argparse

def keccak256(data):
    def rot(val, r):
        return ((val << (r % 64)) & 0xffffffffffffffff) | (val >> (64 - (r % 64)))
    state = [[0] * 5 for _ in range(5)]
    rate = 1088 // 8
    data = bytearray(data)
    data.append(0x01)
    while len(data) % rate != rate - 1:
        data.append(0x00)
    data.append(0x80)
    RC = [
        0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
        0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
        0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
        0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
        0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
        0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
        0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
        0x8000000000008080, 0x0000000080000001, 0x8000000080008008
    ]
    r_offsets = [[0, 36, 3, 41, 18], [1, 44, 10, 45, 2], [62, 6, 43, 15, 61], [28, 55, 25, 21, 56], [27, 20, 39, 8, 14]]
    for block_start in range(0, len(data), rate):
        for i in range(rate // 8):
            state[i % 5][i // 5] ^= int.from_bytes(data[block_start + i*8 : block_start + i*8 + 8], 'little')
        for round_rc in RC:
            C = [state[x][0] ^ state[x][1] ^ state[x][2] ^ state[x][3] ^ state[x][4] for x in range(5)]
            D = [C[(x-1)%5] ^ rot(C[(x+1)%5], 1) for x in range(5)]
            for x in range(5):
                for y in range(5): state[x][y] ^= D[x]
            B = [[0] * 5 for _ in range(5)]
            for x in range(5):
                for y in range(5): B[y][(2*x+3*y)%5] = rot(state[x][y], r_offsets[x][y])
            state = B
            new_state = [[0] * 5 for _ in range(5)]
            for y in range(5):
                for x in range(5): new_state[x][y] = state[x][y] ^ ((~state[(x+1)%5][y]) & state[(x+2)%5][y])
            state = new_state
            state[0][0] ^= round_rc
    res = bytearray()
    for y in range(5):
        for x in range(5): res += state[x][y].to_bytes(8, 'little')
    return res[:32]

def canonicalize_type(t):
    t = t.strip()
    if t == 'uint': return 'uint256'
    if t == 'int': return 'int256'
    if t == 'byte': return 'bytes1'
    # Handle arrays
    if '[' in t:
        base = t[:t.find('[')]
        suffix = t[t.find('['):]
        return canonicalize_type(base) + suffix
    return t

def strip_comments(code):
    code = re.sub(r'//.*', '', code)
    code = re.sub(r'/\*.*?\*/', '', code, flags=re.DOTALL)
    return code

def tokenize(code):
    return re.findall(r'[a-zA-Z_][a-zA-Z0-9_]*|==|>=|<=|!=|=>|[{}()\[\];,=]|".*?"|\'.*?\'', code)

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
    def peek(self, n=0): return self.tokens[self.pos + n] if self.pos + n < len(self.tokens) else None
    def consume(self):
        t = self.peek(); self.pos += 1
        return t

def parse_params(tokens):
    p = Parser(tokens)
    params = []
    if p.peek() == '(':
        p.consume()
        while p.peek() and p.peek() != ')':
            ty = p.consume()
            while p.peek() == '[':
                ty += p.consume()
                while p.peek() != ']': ty += p.consume()
                ty += p.consume()
            while p.peek() in ['memory', 'storage', 'calldata', 'indexed']: p.consume()
            name = ""
